const batch = $input.item.json.valueRanges || [];

function sheetName(rangeName) {
  return String(rangeName || '').split('!')[0].replace(/^'/, '').replace(/'$/, '');
}

function parse(range) {
  if (!range?.values || range.values.length < 2) return [];
  const headers = range.values[0].map(h => String(h || '').trim());
  return range.values.slice(1)
    .filter(row => row.some(cell => String(cell || '').trim() !== ''))
    .map(row => Object.fromEntries(headers.map((h, i) => [h, row[i] || ''])));
}

const sheets = {};
for (const r of batch) sheets[sheetName(r.range)] = parse(r);

function normKey(value) {
  return String(value || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '');
}

function get(row, aliases) {
  const map = {};
  for (const [key, value] of Object.entries(row || {})) map[normKey(key)] = value;
  for (const alias of aliases) {
    const value = map[normKey(alias)];
    if (value !== undefined && value !== null && String(value).trim() !== '') return value;
  }
  return '';
}

function escapeHtml(value) {
  return String(value || '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;');
}

function extractFirstUrl(value) {
  const raw = String(value || '').trim();
  const match = raw.match(/https?:\/\/[^\s"'<>]+/i);
  return match ? match[0].replace(/[),.;]+$/g, '') : '';
}

function toNumber(value) {
  const raw = String(value ?? '').trim()
    .replace(/[\s\u00A0\u202F]/g, '')
    .replace(/[^0-9,.-]/g, '');
  if (!raw) return 0;
  const comma = raw.lastIndexOf(',');
  const dot = raw.lastIndexOf('.');
  let normalized = raw;
  if (comma > dot) {
    normalized = raw.replace(/\./g, '').replace(',', '.');
  } else if (dot > comma && comma >= 0) {
    normalized = raw.replace(/,/g, '');
  } else if (comma >= 0) {
    normalized = raw.replace(',', '.');
  }
  const number = Number(normalized);
  return Number.isFinite(number) ? number : 0;
}

function money(value) {
  return 'AUD ' + toNumber(value).toLocaleString('en-AU', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function parseDate(value) {
  const raw = String(value || '').trim();
  if (!raw) return null;
  const direct = new Date(raw);
  if (!isNaN(direct.getTime())) { direct.setHours(0, 0, 0, 0); return direct; }
  const parts = raw.split('/');
  if (parts.length === 3) {
    const parsed = new Date(Number(parts[2]), Number(parts[1]) - 1, Number(parts[0]));
    if (!isNaN(parsed.getTime())) { parsed.setHours(0, 0, 0, 0); return parsed; }
  }
  return null;
}

function formatDate(value) {
  const date = parseDate(value);
  return date ? date.toLocaleDateString('en-AU', { day: '2-digit', month: 'short', year: 'numeric' }) : '';
}

const today = new Date();
today.setHours(0, 0, 0, 0);
const soon = new Date(today.getTime() + 7 * 86400000);

function rawStatus(row) {
  return String(get(row, ['Status']) || '').trim().toUpperCase().replace(/\s+/g, '_');
}

function needsReview(row) {
  const v = String(get(row, ['Need Review', 'Need_Review']) || '').trim().toLowerCase();
  return ['true', 'yes', 'y', '1', 'review'].includes(v);
}

function classify(row) {
  const status = rawStatus(row);
  const value = toNumber(get(row, ['Amount', 'Amount_Inc_GST', 'Amount_AUD']));
  const due = parseDate(get(row, ['Date Paid', 'Due_Date', 'Due Date']));
  if (['PAID', 'AUTO_PAID', 'DEPOSIT_PAID', 'CANCELLED', 'VOID'].includes(status)) return needsReview(row) ? 'REVIEW' : null;
  if (value > 0 && due && due < today) return 'OVERDUE';
  if (value > 0 && due && due <= soon) return 'DUE SOON';
  if (needsReview(row)) return 'REVIEW';
  if (['PENDING', 'PARTIALLY_PAID', 'UNPAID', 'OPEN', 'AWAITING_PAYMENT'].includes(status) && value > 0) return 'PENDING';
  return null;
}

function reasonFor(item) {
  if (item.category === 'OVERDUE') return 'Overdue since ' + item.dueText;
  if (item.category === 'DUE SOON') return 'Due by ' + item.dueText;
  if (item.category === 'REVIEW') return 'Needs review';
  return 'Pending payment';
}

const payments = sheets.Payments || [];
let allItems = payments.map(row => {
  const category = classify(row);
  if (!category) return null;
  return {
    category,
    vendor: get(row, ['Expense Type', 'Source_Tab']) || 'Payment',
    amount: toNumber(get(row, ['Amount'])),
    amountText: money(get(row, ['Amount'])),
    status: rawStatus(row).replaceAll('_', ' ') || 'UNKNOWN',
    due: parseDate(get(row, ['Date Paid', 'Due_Date', 'Due Date'])),
    dueText: formatDate(get(row, ['Date Paid', 'Due_Date', 'Due Date'])),
    title: String(get(row, ['Description/Task', 'Notes']) || '').trim(),
    link: extractFirstUrl(get(row, ['Links to Gmail', 'Linked Documents', 'Drive_Link']))
  };
}).filter(Boolean);

if (!allItems.length) return [];

const priority = { 'OVERDUE': 1, 'DUE SOON': 2, 'PENDING': 3, 'REVIEW': 4 };
allItems.sort((a, b) => (priority[a.category] || 9) - (priority[b.category] || 9) || (a.due && b.due ? a.due - b.due : b.amount - a.amount));

const shown = allItems.slice(0, 6);
const hidden = allItems.length - shown.length;
let msg = 'PAYER_A House Tracker - Payment Alerts\n';
msg += shown.length + ' priority item(s) shown';
if (hidden > 0) msg += ' / ' + allItems.length + ' total';
msg += '\n\n';

shown.forEach((item, index) => {
  msg += String(index + 1) + '. ' + escapeHtml(item.title || item.vendor).slice(0, 120) + '\n';
  msg += '   ' + escapeHtml(item.amountText) + ' - ' + escapeHtml(item.status) + '\n';
  msg += '   ' + escapeHtml(reasonFor(item)) + '\n';
  msg += item.link ? '   Open: <a href="' + escapeHtml(item.link) + '">source</a>\n' : '   Open: no link found in tracker\n';
  msg += '\n';
});

if (hidden > 0) msg += hidden + ' more item(s) hidden. Ask the bot for all payment alerts.\n';
msg = msg.trim();
if (msg.length > 3900) msg = msg.slice(0, 3800).trim() + '\n\nMessage shortened. Ask the bot for the full list.';

return [{ json: {
  message: msg,
  parse_mode: 'HTML',
  disable_web_page_preview: true,
  totalAlertCount: allItems.length,
  shownAlertCount: shown.length,
  hiddenAlertCount: hidden,
  overdueCount: allItems.filter(i => i.category === 'OVERDUE').length,
  dueSoonCount: allItems.filter(i => i.category === 'DUE SOON').length,
  reviewCount: allItems.filter(i => i.category === 'REVIEW').length
}}];
